            }
            return num;
        }
		private bool IsExistStationIndexOnBSP(int stationIndex) {
            for (int i = 0; i < m_pSetupParam.stations.Length; i++)
            {
                if (m_pSetupParam.stations[i] == stationIndex)
                    return true;
            }
            return false;
        }
		private int countBits(byte bits) {
            return (bits & 1) + ((bits >> 1) & 1) + ((bits >> 2) & 1) + ((bits >> 3) & 1) +
                   ((bits >> 4) & 1) + ((bits >> 5) & 1) + ((bits >> 6) & 1) + (bits >> 7);
        }
		private int SendReliablePacket(global::INL1.PacketWriterRe pwRe, int stationIndex) {
            return NetworkManager.SendReliablePacket(pwRe, stationIndex, UseTransportType);
        }
		private int SendReliableData<T>(global::Dpr.NetworkUtils.ANetData<T> data, int stationIndex) where T : struct {
            return data.SendReliableData(stationIndex, UseTransportType);
        }
		static Client() { }
		private struct SendToClientReq
		{
			public const int HEADER_SIZE = 17;
			public const int WRITABLE_SIZE = 1007;
			public ulong sendBuf;
			public int sendSize;
			public int donenum;
			public int GetDivNum() {
                return GetDivNum(sendSize);
            }
			public bool GetOfs(out int outOfs, out int outBytes, int index) {
                return GetOfs(out outOfs, out outBytes, sendSize, index);
            }
			public static int GetDivNum(int size) {
                if (size == 0)
                    return 0;

                int divNum = size / WRITABLE_SIZE;
                if (size % WRITABLE_SIZE > 0)
                    divNum++;
                return divNum;
            }
			public static bool GetOfs(out int outOfs, out int outBytes, int size, int index) {
                int divNum = GetDivNum(size);
                if (index >= divNum)
                {
                    outOfs = 0;
                    outBytes = 0;
                    return false;
                }
                outOfs = index * WRITABLE_SIZE;
                int bytes = WRITABLE_SIZE;
                if (index >= divNum - 1)
                {
                    int rest = size % WRITABLE_SIZE;
                    if (rest != 0)
                        bytes = rest;
                }
                outBytes = bytes;
                return true;
            }
			public void Set(ulong pSendBuf, int sendSize) {
                sendBuf = pSendBuf;
                this.sendSize = sendSize;
            }
			public void Clear() {
                sendBuf = 0;
                sendSize = 0;
                donenum = 0;
            }
		}
