		private struct SendSeverVersionReq
		{
			public ushort receivedFlag;
			public byte interval;
			public void SetReceivedFlag(ushort flag) {
                receivedFlag = flag;
            }
			public bool SetReceivedFlagRange(byte src, byte flag) {
                ushort oldFlag = receivedFlag;
                int shift = src * 4;
                int mask = 0xF << shift;
                receivedFlag = (ushort)((oldFlag & ~mask) | ((flag << shift) & mask));
                return oldFlag != receivedFlag;
            }
			public int countNum(int src) {
                int bits = receivedFlag >> (src * 4);
                return (bits & 1) + ((bits >> 1) & 1) + ((bits >> 2) & 1) + ((bits >> 3) & 1);
            }
		}
